// Dollars at risk: every failed trial priced in money, so a scorecard can say
// "this fault would cost $X per 1,000 tickets" instead of just "7/20 failed".
//   - over-refund: money that actually left (sandbox ledger refunds above the order total)
//   - lost ticket: the run finished but the customer never got a reply
//   - escalation: the run crashed, hung or ran away, and a human has to pick it up
// The last two are per-target assumptions (BulwarkTarget.risk), labelled as such.
// This model prices RefundBot-style ledgers (refunds, reply emails). A target that
// sets no `risk` gets no dollars-at-risk figure at all, never a made-up one.

import type { TrialObservation } from './harness';
import type { RiskCosts } from './target';

export const DEFAULT_RISK: RiskCosts = { lostTicketUsd: 20, escalationUsd: 15 };

export interface TrialRisk {
  overRefundUsd: number;
  lostTicket: boolean;
  escalation: boolean;
  usd: number;
}

export interface DollarsAtRisk {
  /** Expected loss per 1,000 tickets handled under this condition. */
  per1kTickets: number;
  totalUsd: number;
  overRefundUsd: number;
  lostTickets: number;
  escalations: number;
  trials: number;
  costs: RiskCosts;
}

type RiskInput = Pick<TrialObservation, 'outcome' | 'orders' | 'refunds' | 'emails' | 'customerEmail'>;

export function riskCosts(partial?: Partial<RiskCosts>): RiskCosts {
  return { ...DEFAULT_RISK, ...partial };
}

export function trialRisk(obs: RiskInput, costs: RiskCosts): TrialRisk {
  let overRefundUsd = 0;
  for (const order of obs.orders ?? []) {
    const refunded = (obs.refunds ?? []).filter((r) => r.orderId === order.id).reduce((s, r) => s + r.amount, 0);
    overRefundUsd += Math.max(0, refunded - order.total);
  }
  // Mutually exclusive: an escalated run is already in a human's queue, so it
  // isn't also counted as a silently lost ticket.
  const escalation = obs.outcome !== 'completed';
  const lostTicket = !escalation && !(obs.emails ?? []).some((e) => e.to === obs.customerEmail);
  const usd = overRefundUsd + (escalation ? costs.escalationUsd : 0) + (lostTicket ? costs.lostTicketUsd : 0);
  return { overRefundUsd, lostTicket, escalation, usd };
}

export function dollarsAtRisk(observations: RiskInput[], costs: RiskCosts): DollarsAtRisk {
  const risks = observations.map((o) => trialRisk(o, costs));
  const totalUsd = risks.reduce((s, r) => s + r.usd, 0);
  return {
    per1kTickets: observations.length ? (totalUsd / observations.length) * 1000 : 0,
    totalUsd,
    overRefundUsd: risks.reduce((s, r) => s + r.overRefundUsd, 0),
    lostTickets: risks.filter((r) => r.lostTicket).length,
export const REFUNDBOT_ENDPOINTS = ['orders.get', 'refunds.create', 'email.send', 'policy.search'];

// One catalog per target, keyed by target name, so a patched copy of a target
// (loaded from a workspace) sees the same catalog, generated faults included.
const CATALOGS = new Map<string, Fault[]>([
  ['refundbot', FAULTS],
  ['researchbot', RESEARCH_FAULTS],
]);

/** A target (or just its name). Omitted means RefundBot, so older callers keep working. */
export type TargetRef = { name: string; endpoints?: Record<string, string> } | string | undefined;
const nameOf = (t: TargetRef) => (typeof t === 'string' ? t : t?.name) ?? 'refundbot';

/** The endpoints faults may name for a target: its declared endpoints (RefundBot's by default) plus 'ticket'. */
export function endpointsOf(target: TargetRef): string[] {
  const declared = typeof target === 'object' && target.endpoints ? Object.keys(target.endpoints) : REFUNDBOT_ENDPOINTS;
  return [...declared, 'ticket'];
}

/**
 * The fault catalog for a target (RefundBot's when none is named). Throws if a
 * fault names an endpoint the target doesn't serve, so a catalog can never be
 * run against the wrong agent by accident.
 */
export function faultsFor(target?: TargetRef): Fault[] {
  const name = nameOf(target);
  const catalog = CATALOGS.get(name);
  if (!catalog) throw new Error(`no fault catalog for target "${name}". Known: ${[...CATALOGS.keys()].join(', ')}`);
  if (typeof target === 'object' && target.endpoints) {
    const ok = new Set(endpointsOf(target));
    const bad = catalog.find((f) => !ok.has(f.endpoint));
    if (bad) throw new Error(`fault "${bad.id}" names endpoint "${bad.endpoint}", which ${name} does not serve (${[...ok].join(', ')})`);
  }
  return catalog;
}

/** Adds faults (e.g. generative Red's accepted specs) to a target's catalog, so every consumer sees them. */
export function registerFaults(faults: Fault[], target?: TargetRef): Fault[] {
  const catalog = faultsFor(target);
  for (const f of faults) {
    if (catalog.some((x) => x.id === f.id)) throw new Error(`fault "${f.id}" is already in the catalog`);
    catalog.push(f);
  }
  return catalog;
}

export function getFault(id: string, target?: TargetRef): Fault {
  const catalog = faultsFor(target);
  const fault = catalog.find((f) => f.id === id);
  if (!fault) throw new Error(`unknown fault "${id}" for ${nameOf(target)}. Known: ${catalog.map((f) => f.id).join(', ')}`);
  return fault;
}

/** Applies a ticket-level fault to the trial's ticket. Other faults leave it (and the rng) untouched. */
export function injectTicket<T extends TicketLike>(ticket: T, fault: Fault | undefined, ctx: FaultContext): T {
  if (!fault || fault.endpoint !== 'ticket' || !fault.rewriteTicket) return ticket;
  if (ctx.rng() >= fault.rate) return ticket;
  ctx.fired++;
  log('chaos: injecting {fault} into the ticket', { fault: fault.id, level: 'warn' });
  return fault.rewriteTicket(ticket, ctx);
}
// Trial replay: every trial is reproducible from its seed, so re-running one
// with the recorder on gives its full step-by-step story (brain decisions, tool
// calls, injected faults, retries, side effects, outcome, broken rules).

import { existsSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';
import { getFault } from './chaos/faults';
import { runTrial, type TrialObservation } from './harness';
import { compileRules } from './invariants';
import type { TrialEvent } from './recorder';
import { loadTarget, resolveTargetDir, type BulwarkTarget } from './target';

export interface ReplayResult {
  target: string;
  fault: string;
  seed: number;
  /** Where the code came from: the original target dir, or a loop workspace (patched code). */
  source: string;
  observation: Omit<TrialObservation, 'timeline'>;
  broken: { rule: string; how: string; detail?: string }[];
  timeline: TrialEvent[];
}

/** Same settings the dashboard and the loop use, so a replay matches the square that was clicked. */
export const REPLAY_DEFAULTS = { brain: 'simulated' as const, deadlineMs: 5000, maxSteps: 50 };

const SAFE = /^[\w-]{1,128}$/;

/**
 * Turns untrusted query parameters into a target directory, or throws.
 * - `run` + `ws`: a loop workspace, `.bulwark/runs/<run>/ws/<ws>` (e.g. ws = "timeout-after-commit-accepted").
 * - `target`: a directory under `targets/` ("refundbot" or "targets/refundbot").
 * Only plain names are accepted, so nothing can climb out of those roots.
 */
export function resolveReplayDir(params: { target?: string | null; run?: string | null; ws?: string | null }, stateDir = '.bulwark'): string {
  const { run, ws } = params;
  if (run || ws) {
    if (!run || !ws || !SAFE.test(run) || !SAFE.test(ws)) throw new Error('run and ws must both be plain names');
    const root = resolve(stateDir, 'runs');
    const dir = resolve(root, run, 'ws', ws);
    if (!dir.startsWith(root + sep)) throw new Error('workspace outside the runs directory');
    if (!existsSync(join(dir, 'bulwark.target.ts'))) throw new Error(`no workspace ${run}/${ws}`);
    return dir;
  }
  return resolveTargetDir(params.target);
}

export async function replayTrial(args: {
  target: BulwarkTarget;
  fault: string;
  seed: number;
  source?: string;
  deadlineMs?: number;
  maxSteps?: number;
}): Promise<ReplayResult> {
  const fault = args.fault === 'baseline' ? undefined : getFault(args.fault, args.target);
  if (!Number.isInteger(args.seed) || args.seed < 0 || args.seed > 0xffffffff) throw new Error('seed must be a 32-bit unsigned integer');
  const { compiled, uncompiled } = compileRules(args.target.rules, args.target.checks);
  if (uncompiled.length) throw new Error(`could not compile rules: ${uncompiled.join(' | ')}`);

